  ('a46175e6-4ba5-55fe-a73d-b4f5eef9c65d'::uuid, 'bcn-marisol-north-point', 'insert_new', 'Marisol North Point', 'marisol-north-point', 'Rosarito', 'Baja California', 'Mexico', 'Baja Norte', 'America/Tijuana', 32.398, -117.092, 'point', 'advanced', ARRAY['rocks', 'rips']::text[], ARRAY['point']::text[], ARRAY['rocks', 'rips', 'Legal access and parking have not been field verified', 'Hazards and local conditions may change; verify locally', 'Map pin is generalized and is not a navigation or access point']::text[], 'Marisol North Point is a point surf spot near Rosarito, Baja California, Mexico. The source profile describes it as exposed and consistent.', 'A parking lot faces the break directly, street parking is available when the lot fills. Being near the main public beach means basic amenities are close, but this is Lake Michigan in winter: pack warm layers, hot drinks, and dry bags. The current risk on south-wind days is serious, if swept around the point, ride the current shoreward, exit the water, and re-paddle from further down the beach.', 'The source reports WNW as the ideal swell direction; this is a soft directional prior, not a validated acceptance window. Reported offshore wind is E.', 'Usually uncrowded', 'Static source guidance only. Check the live Quiver forecast and local conditions before paddling out.', ARRAY[9, 10, 11, 12, 1, 2]::integer[], 90, NULL, NULL, NULL, NULL, NULL, 0, 90, 45, 45, NULL, NULL, 'either', NULL, '{"version":"baja-production-enrichment-v2","usage":"editorial_swell_windows_with_session_calibration_pending","source_break_categories":["point"],"source_quality_rating_5":2,"source_reliability":{"category":"consistent","ordinal_1_to_5":4,"interpretation":"Ordinal normalization of the source category; not a probability."},"source_exposure":"exposed","soft_swell_direction_prior":{"center_deg":292.5,"half_width_deg":22.5,"min_deg":270,"max_deg":315,"wraps_north":false,"usage":"ranking_feature_only","not_a_hard_acceptance_window":true,"co