  ('63b839db-90fa-564a-8b3b-6ed53a00aa57'::uuid, 'bcn-calafia', 'insert_new', 'Calafia', 'calafia', 'Popotla', 'Baja California', 'Mexico', 'Baja Norte', 'America/Tijuana', 32.2668, -117.018, 'point', 'advanced', ARRAY['rocks', 'pollution']::text[], ARRAY['point']::text[], ARRAY['rocks', 'pollution', 'Legal access and parking have not been field verified', 'Hazards and local conditions may change; verify locally', 'Map pin is generalized and is not a navigation or access point']::text[], 'Calafia is a point surf spot near Popotla, Baja California, Mexico. The source profile describes it as exposed and fairly consistent.', 'Drive south on Highway 1 libre toward Ensenada, roughly 30 minutes from the border past Mushrooms. There is a paid car park. A well-worn footpath descends the cliff. Time your paddle-out carefully, as rocks and shore break demand attention. No surf facilities on site, but hotels, restaurants, and clubs line the cliff. Water quality is fair at best.', 'The source reports S as the ideal swell direction; this is a soft directional prior, not a validated acceptance window. Reported offshore wind is NNW. Reported tide guidance: high_rising.', 'Usually uncrowded', 'Static source guidance only. Check the live Quiver forecast and local conditions before paddling out.', ARRAY[6, 7, 8]::integer[], 338, NULL, NULL, NULL, NULL, NULL, 180, 225, 202.5, 22.5, NULL, NULL, 'either', NULL, '{"version":"baja-production-enrichment-v2","usage":"editorial_swell_windows_with_session_calibration_pending","source_break_categories":["point"],"source_quality_rating_5":3,"source_reliability":{"category":"fairly_consistent","ordinal_1_to_5":3,"interpretation":"Ordinal normalization of the source category; not a probability."},"source_exposure":"exposed","soft_swell_direction_prior":{"center_deg":180,"half_width_deg":22.5,"min_deg":157.5,"max_deg":202.5,"wraps_north":false,"usage":"ranking_feature_only","not_a_hard_acceptance_window":true,"confidence":"low"},"reported_tide_gui