  ('66c07a7b-77ce-50f2-8838-856a84b78716'::uuid, 'bcn-salsipuedes', 'insert_new', 'Salsipuedes', 'salsipuedes', 'Municipio de Ensenada', 'Baja California', 'Mexico', 'Baja Norte', 'America/Tijuana', 31.9763652271726, -116.791388895755, 'point', 'advanced', ARRAY['rocks']::text[], ARRAY['reef', 'point']::text[], ARRAY['rocks', 'Legal access and parking have not been field verified', 'Hazards and local conditions may change; verify locally', 'Map pin is generalized and is not a navigation or access point']::text[], 'Salsipuedes is a point surf spot near Municipio de Ensenada, Baja California, Mexico. The source profile describes it as exposed and fairly consistent. Reported waves run left and right.', 'No land access since 2007. A boat is the only way in. There are no facilities on site. Launch from Ensenada and plan accordingly with food, water, and fuel. Shallow rock sections demand attention on the inside, and the primary hazard is a long boat ride for skunked conditions on an inconsistent break. Check forecasts obsessively before committing.', 'The source reports SW as the ideal swell direction; this is a soft directional prior, not a validated acceptance window. Reported offshore wind is NNE.', 'Usually uncrowded', 'Static source guidance only. Check the live Quiver forecast and local conditions before paddling out.', ARRAY[6, 7, 8]::integer[], 23, NULL, NULL, NULL, NULL, NULL, 202.5, 247.5, 225, 22.5, NULL, NULL, 'either', NULL, '{"version":"baja-production-enrichment-v2","usage":"editorial_swell_windows_with_session_calibration_pending","source_break_categories":["reef","point"],"source_quality_rating_5":3,"source_reliability":{"category":"fairly_consistent","ordinal_1_to_5":3,"interpretation":"Ordinal normalization of the source category; not a probability."},"source_exposure":"exposed","soft_swell_direction_prior":{"center_deg":225,"half_width_deg":22.5,"min_deg":202.5,"max_deg":247.5,"wraps_north":false,"usage":"ranking_feature_only","not_a_hard_acceptance_w