  ('eceeb33f-1bc6-5fe4-b3b0-b6b5610849fe'::uuid, 'bcn-san-miguel', 'insert_new', 'San Miguel', 'san-miguel', 'Ensenada', 'Baja California', 'Mexico', 'Baja Norte', 'America/Tijuana', 31.9001651947431, -116.731165956641, 'point', 'intermediate', ARRAY['urchins', 'rocks', 'pollution']::text[], ARRAY['point']::text[], ARRAY['urchins', 'rocks', 'pollution', 'locals', 'Legal access and parking have not been field verified', 'Hazards and local conditions may change; verify locally', 'Map pin is generalized and is not a navigation or access point']::text[], 'San Miguel is a point surf spot near Ensenada, Baja California, Mexico. The source profile describes it as exposed and consistent. Reported waves run left and right.', 'Park in the dirt lot at the point. Camping is available on-site for a fee. Ensenada is the nearest town with full services, food, water, and accommodation. The river mouth at the takeoff zone carries runoff that makes water quality suspect, especially after rain. Rocks and occasional urchins are the primary physical hazards.', 'The source reports WNW as the ideal swell direction; this is a soft directional prior, not a validated acceptance window. Reported offshore wind is E.', 'Crowded when working', 'Static source guidance only. Check the live Quiver forecast and local conditions before paddling out.', ARRAY[9, 10, 11, 12, 1, 2]::integer[], 90, NULL, NULL, NULL, NULL, NULL, 247.5, 315, 281.25, 33.75, NULL, NULL, 'either', NULL, '{"version":"baja-production-enrichment-v2","usage":"editorial_swell_windows_with_session_calibration_pending","source_break_categories":["point"],"source_quality_rating_5":3,"source_reliability":{"category":"consistent","ordinal_1_to_5":4,"interpretation":"Ordinal normalization of the source category; not a probability."},"source_exposure":"exposed","soft_swell_direction_prior":{"center_deg":292.5,"half_width_deg":22.5,"min_deg":270,"max_deg":315,"wraps_north":false,"usage":"ranking_feature_only","not_a_hard_acceptance_window"