  ('a29b713e-3d14-552b-85f5-a3e0a6066645'::uuid, 'bcn-punta-cabras', 'insert_new', 'Punta Cabras', 'punta-cabras', 'Municipio de Ensenada', 'Baja California', 'Mexico', 'Baja Norte', 'America/Tijuana', 31.329, -116.457, 'reef', 'advanced', ARRAY['rocks', 'sharks']::text[], ARRAY['beach', 'reef']::text[], ARRAY['rocks', 'sharks', 'Legal access and parking have not been field verified', 'Hazards and local conditions may change; verify locally', 'Map pin is generalized and is not a navigation or access point']::text[], 'Punta Cabras is a reef surf spot near Municipio de Ensenada, Baja California, Mexico. The source profile describes it as exposed and consistent. Reported waves run left and right.', 'Head south from Ensenada, exit toward Ejido Erendira from Highway 1, then work north along the coast. The road becomes a dirt track and demands a spare tire at minimum, 4x4 after rain. No formal facilities: bring everything you need including water, food, and firewood. The coastline has rocky sections with mussels at the water''s edge, so watch your footing.', 'The source reports W as the ideal swell direction; this is a soft directional prior, not a validated acceptance window. Reported offshore wind is ENE.', 'Rarely crowded', 'Static source guidance only. Check the live Quiver forecast and local conditions before paddling out.', ARRAY[9, 10, 11, 12, 1, 2]::integer[], 68, NULL, NULL, NULL, NULL, NULL, 225, 315, 270, 45, NULL, NULL, 'either', NULL, '{"version":"baja-production-enrichment-v2","usage":"editorial_swell_windows_with_session_calibration_pending","source_break_categories":["beach","reef"],"source_quality_rating_5":2,"source_reliability":{"category":"consistent","ordinal_1_to_5":4,"interpretation":"Ordinal normalization of the source category; not a probability."},"source_exposure":"exposed","soft_swell_direction_prior":{"center_deg":270,"half_width_deg":22.5,"min_deg":247.5,"max_deg":292.5,"wraps_north":false,"usage":"ranking_feature_only","not_a_hard_acceptance