  ('64ed2560-ffcc-5f04-95f9-d722ab214a23'::uuid, 'bcn-punta-baja', 'insert_new', 'Punta Baja', 'punta-baja', 'El Rosario', 'Baja California', 'Mexico', 'Baja Norte', 'America/Tijuana', 29.941, -115.817, 'reef', 'advanced', ARRAY['rocks']::text[], ARRAY['beach', 'reef']::text[], ARRAY['rocks', 'Legal access and parking have not been field verified', 'Hazards and local conditions may change; verify locally', 'Map pin is generalized and is not a navigation or access point']::text[], 'Punta Baja is a reef surf spot near El Rosario, Baja California, Mexico. The source profile describes it as exposed and inconsistent. Reported waves run left and right.', 'From El Rosario, turn right at the first mercado and take the first dirt road heading west. There is a makeshift bridge over a stream en route. Follow west past the village toward the radar tower on the hill, a sign marks the turn. Keep right to avoid ending up at Punta Carlos. There are no facilities. Cliffs above the beach offer a camp setup with a stairway down. Bring all supplies including water, fuel, and food from El Rosario.', 'The source reports W as the ideal swell direction; this is a soft directional prior, not a validated acceptance window. Reported offshore wind is E.', 'Rarely crowded', 'Static source guidance only. Check the live Quiver forecast and local conditions before paddling out.', ARRAY[12, 1, 2]::integer[], 90, NULL, NULL, NULL, NULL, NULL, 270, 315, 292.5, 22.5, NULL, NULL, 'either', NULL, '{"version":"baja-production-enrichment-v2","usage":"editorial_swell_windows_with_session_calibration_pending","source_break_categories":["beach","reef"],"source_quality_rating_5":2,"source_reliability":{"category":"inconsistent","ordinal_1_to_5":2,"interpretation":"Ordinal normalization of the source category; not a probability."},"source_exposure":"exposed","soft_swell_direction_prior":{"center_deg":270,"half_width_deg":22.5,"min_deg":247.5,"max_deg":292.5,"wraps_north":false,"usage":"ranking_feature_only","n