  ('f7505c91-f56c-555c-bf83-43c6c112de51'::uuid, 'bcn-punta-rosarito', 'insert_new', 'Punta Rosarito (The Wall)', 'punta-rosarito-the-wall', 'Santa Rosalillita', 'Baja California', 'Mexico', 'Baja Norte', 'America/Tijuana', 28.551, -114.15, 'reef', 'intermediate', ARRAY['rips', 'sharks', 'rocks', 'urchins', 'theft']::text[], ARRAY['reef']::text[], ARRAY['rips', 'sharks', 'rocks', 'urchins', 'theft', 'Legal access and parking have not been field verified', 'Hazards and local conditions may change; verify locally', 'Map pin is generalized and is not a navigation or access point']::text[], 'Punta Rosarito (The Wall) is a reef surf spot near Santa Rosalillita, Baja California, Mexico. The source profile describes it as exposed and consistent. Reported waves run left and right.', 'Dirt road access through the Baja interior requires a capable vehicle, especially after rain. Free camping is available beside the rock wall windbreaks. No formal facilities, so pack water, fuel, and food for multiple days. The nearest supply point is a significant drive, so come prepared. Urchins on the reef are a hazard worth reef booties.', 'The source reports NW as the ideal swell direction; this is a soft directional prior, not a validated acceptance window. Reported offshore wind is NE.', 'Sometimes crowded', 'Static source guidance only. Check the live Quiver forecast and local conditions before paddling out.', ARRAY[12, 1, 2]::integer[], 45, NULL, NULL, NULL, NULL, NULL, 270, 315, 292.5, 22.5, NULL, NULL, 'either', NULL, '{"version":"baja-production-enrichment-v2","usage":"editorial_swell_windows_with_session_calibration_pending","source_break_categories":["reef"],"source_quality_rating_5":1,"source_reliability":{"category":"consistent","ordinal_1_to_5":4,"interpretation":"Ordinal normalization of the source category; not a probability."},"source_exposure":"exposed","soft_swell_direction_prior":{"center_deg":315,"half_width_deg":22.5,"min_deg":292.5,"max_deg":337.5,"wraps_north":false,"