  ('6c2b7e38-dd41-5593-8123-dba5f9e759c2'::uuid, 'bcs-punta-abreojos', 'insert_new', 'Punta Abreojos', 'punta-abreojos', 'Punta Abreojos', 'Baja California Sur', 'Mexico', 'Baja Sur', 'America/Mazatlan', 26.7489, -113.527, 'point', 'intermediate', ARRAY['rips', 'sharks', 'rocks', 'isolation']::text[], ARRAY['point']::text[], ARRAY['rips', 'sharks', 'rocks', 'isolation', 'Legal access and parking have not been field verified', 'Hazards and local conditions may change; verify locally', 'Map pin is generalized and is not a navigation or access point']::text[], 'Punta Abreojos is a point surf spot near Punta Abreojos, Baja California Sur, Mexico. The source profile describes it as exposed and consistent.', 'The road from the Baja 1 turnoff involves stretches of washboard dirt regardless of paving progress. Paid camping is available directly in front of the breaks. No formal surf shops, so arrive self-sufficient: extra water, sunscreen, ding repair, and fuel. Fresh fish is available from the co-op. Sharks are a real and documented presence, locals and visiting divers have confirmed large hammerheads working the area, especially near gill nets.', 'The source reports SSW as the ideal swell direction; this is a soft directional prior, not a validated acceptance window. Reported offshore wind is NNW.', 'Rarely crowded', 'Static source guidance only. Check the live Quiver forecast and local conditions before paddling out.', ARRAY[6, 7, 8]::integer[], 338, NULL, NULL, NULL, NULL, NULL, 180, 225, 202.5, 22.5, NULL, NULL, 'either', NULL, '{"version":"baja-production-enrichment-v2","usage":"editorial_swell_windows_with_session_calibration_pending","source_break_categories":["point"],"source_quality_rating_5":1,"source_reliability":{"category":"consistent","ordinal_1_to_5":4,"interpretation":"Ordinal normalization of the source category; not a probability."},"source_exposure":"exposed","soft_swell_direction_prior":{"center_deg":202.5,"half_width_deg":22.5,"min_deg":180,"max_deg":2