  ('ee68a84a-9e5e-5012-a8ae-cd6a45d3a110'::uuid, 'bcs-scorpion-bay-san-juanico', 'insert_new', 'Scorpion Bay (San Juanico)', 'scorpion-bay-san-juanico', 'San Juanico', 'Baja California Sur', 'Mexico', 'Baja Sur', 'America/Mazatlan', 26.2424, -112.475, 'point', 'intermediate', ARRAY['urchins', 'rocks']::text[], ARRAY['point']::text[], ARRAY['urchins', 'rocks', 'Legal access and parking have not been field verified', 'Hazards and local conditions may change; verify locally', 'Map pin is generalized and is not a navigation or access point']::text[], 'Scorpion Bay (San Juanico) is a point surf spot near San Juanico, Baja California Sur, Mexico. The source profile describes it as exposed and inconsistent.', 'The drive from Tijuana runs 800-plus miles, roughly 14 hours on paved road, followed by 100-300 miles of rugged off-road desert track depending on which route you take. No accommodations exist. Camping is on a lava bluff with cold showers, rationed water, and a fee that has climbed over the years. Bring all food, fuel, and first aid. Urchins on the reef are the main in-water hazard.', 'The source reports SSW as the ideal swell direction; this is a soft directional prior, not a validated acceptance window. Reported offshore wind is WNW.', NULL, 'Static source guidance only. Check the live Quiver forecast and local conditions before paddling out.', ARRAY[6, 7, 8]::integer[], 293, NULL, NULL, NULL, NULL, NULL, 180, 225, 202.5, 22.5, NULL, NULL, 'either', NULL, '{"version":"baja-production-enrichment-v2","usage":"editorial_swell_windows_with_session_calibration_pending","source_break_categories":["point"],"source_quality_rating_5":4,"source_reliability":{"category":"inconsistent","ordinal_1_to_5":2,"interpretation":"Ordinal normalization of the source category; not a probability."},"source_exposure":"exposed","soft_swell_direction_prior":{"center_deg":202.5,"half_width_deg":22.5,"min_deg":180,"max_deg":225,"wraps_north":false,"usage":"ranking_feature_only","not_a_hard_ac