  ('15b1b54e-89c1-5b14-8943-67d1515ae7c0'::uuid, 'bcs-punta-conejo', 'insert_new', 'Punta Conejo', 'punta-conejo', 'La Paz', 'Baja California Sur', 'Mexico', 'Baja Sur', 'America/Mazatlan', 24.0718, -111.0069, 'point', 'intermediate', ARRAY['rips']::text[], ARRAY['point']::text[], ARRAY['rips', 'Legal access and parking have not been field verified', 'Hazards and local conditions may change; verify locally', 'Map pin is generalized and is not a navigation or access point']::text[], 'Punta Conejo is a point surf spot near La Paz, Baja California Sur, Mexico. The source profile describes it as exposed and consistent. Reported waves run left.', 'The turnoff is signed from the highway. Expect roughly an hour on a rough dirt road. Park on the bluff. No shops, no water, no facilities beyond what you bring. Haul in enough water, food, and fuel for at least two to three days. Block ice lasts longer than cubed. Local fishermen near the lighthouse sometimes sell fresh catch directly. Strong afternoon winds make secure tarp setup essential.', 'The source reports SW as the ideal swell direction; this is a soft directional prior, not a validated acceptance window. Reported offshore wind is NE.', 'Rarely crowded', 'Static source guidance only. Check the live Quiver forecast and local conditions before paddling out.', ARRAY[]::integer[], 45, NULL, NULL, NULL, NULL, NULL, 202.5, 247.5, 225, 22.5, NULL, NULL, 'either', NULL, '{"version":"baja-production-enrichment-v2","usage":"editorial_swell_windows_with_session_calibration_pending","source_break_categories":["point"],"source_quality_rating_5":3,"source_reliability":{"category":"consistent","ordinal_1_to_5":4,"interpretation":"Ordinal normalization of the source category; not a probability."},"source_exposure":"exposed","soft_swell_direction_prior":{"center_deg":225,"half_width_deg":22.5,"min_deg":202.5,"max_deg":247.5,"wraps_north":false,"usage":"ranking_feature_only","not_a_hard_acceptance_window":true,"confidence":"low"},"report