  ('32902ed8-5a5e-57e5-9385-cc3eef938dcf'::uuid, 'bcs-monuments', 'insert_new', 'Monuments', 'monuments', 'El Tezal', 'Baja California Sur', 'Mexico', 'Baja Sur', 'America/Mazatlan', 22.896, -109.869, 'point', 'advanced', ARRAY['rips', 'rocks', 'urchins', 'pollution']::text[], ARRAY['point']::text[], ARRAY['rips', 'rocks', 'urchins', 'pollution', 'Legal access and parking have not been field verified', 'Hazards and local conditions may change; verify locally', 'Map pin is generalized and is not a navigation or access point']::text[], 'Monuments is a point surf spot near El Tezal, Baja California Sur, Mexico. The source profile describes it as exposed and very consistent. Reported waves run left.', 'Drive east from Cabo San Lucas toward San Jose del Cabo. Access runs through a guarded hotel gate, security typically allows surfers through. Park above the break and take the dirt trail down. After a session, the hotel above the break serves cold beers with a direct view of the arch. Water quality is clean.', 'The source reports SSE as the ideal swell direction; this is a soft directional prior, not a validated acceptance window. Reported offshore wind is NW. Reported tide guidance: mid_tide.', 'Crowded when working', 'Static source guidance only. Check the live Quiver forecast and local conditions before paddling out.', ARRAY[6, 7, 8]::integer[], 315, NULL, NULL, NULL, NULL, NULL, 180, 270, 225, 45, NULL, NULL, 'either', NULL, '{"version":"baja-production-enrichment-v2","usage":"editorial_swell_windows_with_session_calibration_pending","source_break_categories":["point"],"source_quality_rating_5":3,"source_reliability":{"category":"very_consistent","ordinal_1_to_5":5,"interpretation":"Ordinal normalization of the source category; not a probability."},"source_exposure":"exposed","soft_swell_direction_prior":{"center_deg":157.5,"half_width_deg":22.5,"min_deg":135,"max_deg":180,"wraps_north":false,"usage":"ranking_feature_only","not_a_hard_acceptance_window":true,"confiden