SELECT
  s.id, s.name, s.slug, s.city, s.state, s.country, s.region, s.timezone,
  s.lat, s.lon, s.break_type, s.skill_level, s.hazards, s.features,
  s.warnings, s.description, s.access_tips, s.wave_tips, s.crowd_tips,
